    const type = frontmatter.type || "concept";
    const tags = frontmatter.tags || [];

    const graph = await loadSemanticGraph(userId);
    const core = await loadCoreMemory(userId);

    const normalizedId = id.toString().trim().toLowerCase().replace(/\s+/g, "_");
    const existingNodeIdx = graph.nodes.findIndex((n: any) => n.id === normalizedId);

    const newNode = {
      id: normalizedId,
      label: name,
      type: ["person", "place", "object", "system", "concept"].includes(type) ? type : "concept",
      tags
    };

    if (existingNodeIdx !== -1) {
      graph.nodes[existingNodeIdx] = { ...graph.nodes[existingNodeIdx], ...newNode };
    } else {
      graph.nodes.push(newNode);
    }

    const logs: string[] = [];
    logs.push(`Successfully validated OKF Frontmatter.`);
    logs.push(`Registered Concept: "${name}" [ID: ${normalizedId}] (${type})`);

    const linksList = frontmatter.links || [];
    let linksAdded = 0;
    for (const link of linksList) {
      if (link.target) {
        const targetId = link.target.toString().trim().toLowerCase().replace(/\s+/g, "_");
        const relationLabel = link.type || link.label || "relates_to";

        if (!graph.nodes.some((n: any) => n.id === targetId)) {
          graph.nodes.push({ id: targetId, label: link.target, type: "concept" });
          logs.push(`Auto-registered linked context node: "${link.target}"`);
        }

        const linkExists = graph.relations.some((r: any) => 
          r.source === normalizedId && r.target === targetId && r.label === relationLabel
        );
        if (!linkExists) {
          graph.relations.push({
            source: normalizedId,
            target: targetId,
            label: relationLabel
          });
          linksAdded++;
        }
      }
    }
    if (linksAdded > 0) {
      logs.push(`Linked ${linksAdded} cognitive network connections successfully.`);
    }

    let profileUpdated = false;
    if (type === "profile" || type === "user") {
      const prof = core.user_profile;
      if (frontmatter.alias) prof.name = frontmatter.alias;
      if (frontmatter.name && !frontmatter.alias) prof.name = frontmatter.name;
      if (frontmatter.job) prof.job = frontmatter.job;
      if (frontmatter.location) prof.location = frontmatter.location;
      if (frontmatter.mission) prof.mission = frontmatter.mission;
      if (frontmatter.mbti) prof.mbti = frontmatter.mbti;
      if (frontmatter.philosophical_core) prof.philosophical_core = frontmatter.philosophical_core;

      profileUpdated = true;
      logs.push(`Synchronized OKF metadata features into active biological profile.`);
    }

    await saveSemanticGraph(graph, userId);
    if (profileUpdated) {
      await saveCoreMemory(core, userId);
    }

    res.json({
      success: true,
      logs,
      node: newNode,
      nodes: graph.nodes,
      relations: graph.relations,
      core: profileUpdated ? core : undefined
    });
  } catch (err) {
    next(err);
  }
});

// CPU load monitor helper
function getCpuInfo() {
  const cpus = os.cpus();
  if (!cpus || cpus.length === 0) return { idle: 0, total: 0 };
  let user = 0;
  let nice = 0;
  let sys = 0;
  let idle = 0;
  let irq = 0;

  for (const cpu of cpus) {
    user += cpu.times.user;
    nice += cpu.times.nice;
    sys += cpu.times.sys;
    idle += cpu.times.idle;
    irq += cpu.times.irq;
  }

  const total = user + nice + sys + idle + irq;
  return { idle, total };
}

let lastCpuInfo = getCpuInfo();

// Robust CPU utilization score
function getCpuUsage(): number {
  const currentCpuInfo = getCpuInfo();
  const idleDifference = currentCpuInfo.idle - lastCpuInfo.idle;
  const totalDifference = currentCpuInfo.total - lastCpuInfo.total;

  lastCpuInfo = currentCpuInfo;

  if (totalDifference === 0) return 0;
  return Math.floor(100 - (100 * idleDifference) / totalDifference);
}

let cachedDiskSpace = "120 GB / 512 GB";
let lastDiskCheck = 0;

async function getDiskSpace(): Promise<string> {
  const now = Date.now();
  if (now - lastDiskCheck < 60000) {
    return cachedDiskSpace;
  }
  lastDiskCheck = now;
  try {
    if (process.platform === "win32") {
      const { stdout } = await execPromise('powershell -Command "Get-CimInstance -ClassName Win32_LogicalDisk | Where-Object {$_.DeviceID -eq \'C:\'} | Select-Object Size, FreeSpace | ConvertTo-Json"');
      const data = JSON.parse(stdout);
      if (data && data.Size) {
        const sizeGB = Math.floor(data.Size / (1024 * 1024 * 1024));
        const freeGB = Math.floor(data.FreeSpace / (1024 * 1024 * 1024));
        const usedGB = sizeGB - freeGB;
        cachedDiskSpace = `${usedGB} GB / ${sizeGB} GB`;
      }
    } else {
      const { stdout } = await execPromise("df -h / | tail -1 | awk '{print $3 \" / \" $2}'");
      if (stdout) {
        cachedDiskSpace = stdout.trim();
      }
    }
  } catch (e) {
    // fallback
  }
  return cachedDiskSpace;
}

