    model: "bitnet",
    messages: [
      {
        role: "system",
        content: "You are a query classifier. Choose exactly one label:\n- ROUTE_SIMPLE: greetings, casual chat, basic facts.\n- ROUTE_TOOL: workspace actions, memory updates, calendar, email, Drive, code edits.\n- ROUTE_REASONING: complex analysis, math, coding problems, multi-step reasoning.\nRespond with ONLY the label."
      },
