    ],
    temperature: 0.1,
    max_tokens: 10
  }, 30000).then(async (res: any) => {
    if (res.ok) {
      const data: any = await res.json();
      const text: string = data.choices?.[0]?.message?.content || "";
      if (text.includes("ROUTE_SIMPLE")) routeHint = "ROUTE_SIMPLE";
      else if (text.includes("ROUTE_TOOL")) routeHint = "ROUTE_TOOL";
      else if (text.includes("ROUTE_REASONING")) routeHint = "ROUTE_REASONING";
      console.log(`[Ternary Classifier] Auto-classified: ${routeHint}`);
    }
  }).catch(() => {
    // Bonsai offline — Gemini handles without hint, zero user impact
    console.log("[Ternary Classifier] Offline — proceeding without route hint.");
  });

  // Save incoming message to persistent logs
  const savedHistory = await loadChatHistory(userId);
  const msgId = "msg_" + Date.now() + "_" + (channel === "telegram" ? "tg_usr" : "usr");
  const displayContent = channel === "telegram" ? `📱 [Telegram Message]: ${message}` : message;

