  let temperature = 0.8;
  if (voltageVal < 0.90) {
    numSamples = 1;
    temperature = 0.45;
  } else if (voltageVal > 1.15) {
    numSamples = 5;
    temperature = 1.1;
  }

  const escapedPrompt = prompt.replace(/"/g, '\\"');
  const escapedModel = selectedModel.replace(/"/g, '\\"');
  const cmd = `python vibe_consensus.py "${escapedPrompt}" "${escapedModel}" --json --samples ${numSamples} --temp ${temperature}`;

  console.log(`[Vibe Consensus] Spawning subprocess: ${cmd}`);

  exec(cmd, (error, stdout, stderr) => {
    if (stderr) {
      console.warn(`[Vibe Consensus Script Logs]:\n${stderr}`);
    }
    if (error) {
      console.error(`[Vibe Consensus Execution Error]:`, error);
      return res.status(500).json({ error: `VibeThinker execution failed: ${error.message}` });
    }

    try {
      const data = JSON.parse(stdout.trim());
      res.json(data);
    } catch (parseErr: any) {
      console.error("[Vibe Consensus Parse Error]: Failed to parse Python stdout:", stdout);
      res.status(500).json({ error: `Failed to parse consensus response: ${parseErr.message}. Output was: ${stdout}` });
    }
  });
});

