      },
      files: {
        robots: robotsExists,
        sitemap: sitemapExists
      },
      intelReport: {
        techStack: matchedStack,
        overview: overviewText,
        postureGrade,
        vulnerabilities: vulnerabilitiesFound,
        recommendations: tacticalRecommendations
      }
